"""Fixed chat texts: sent verbatim by the code, never generated by the LLM.

Texts the user sees are German."""

ANALYST_LABEL = "Analyst"
INTERRUPTED_NOTE = "Die Antwort wurde unterbrochen. Bitte versuchen Sie es erneut."
ROUND_LIMIT_NOTE = (
    "Ich habe hier abgebrochen, weil zu viele Schritte nötig waren. "
    "Bitte formulieren Sie die Anfrage enger."
)
TRUNCATED_NOTE = (
    "Die Antwort war zu lang und wurde abgeschnitten. "
    "Bitte teilen Sie die Anfrage in kleinere Schritte auf."
)
EMPTY_REPLY_OK = "Erledigt."
EMPTY_REPLY_FAILED = "Das hat leider nicht geklappt."
QUESTION_ADDED_NEW = (
    "Die Frage wurde zu 03 hinzugefügt. Da 03 noch nicht existierte, habe ich es angelegt."
)
QUESTION_ADDED = "Die Frage wurde zu 03 hinzugefügt."
QUESTION_ALREADY_IN_03 = "Diese Frage steht bereits in 03."
QUESTIONS_ALREADY_IN_03 = "Diese Fragen stehen bereits in 03."
QUESTION_DECLINED = "Okay, ich füge nichts hinzu."


def questions_added(count: int, *, created: bool) -> str:
    if count == 1:
        text = QUESTION_ADDED_NEW if created else QUESTION_ADDED
        return text
    text = f"{count} Fragen wurden zu 03 hinzugefügt."
    return f"{text} Da 03 noch nicht existierte, habe ich es angelegt." if created else text


GREETING_NEW = (
    "Hallo! Ich helfe Ihnen bei der Vorbereitung des Kundenworkshops. Gemeinsam erstellen wir "
    "drei Artefakte. Sie können mir zunächst Fragen zu den Kundendokumenten stellen oder direkt "
    "mit der Projektbeschreibung beginnen."
)
GREETING_ALL_APPROVED = "Willkommen zurück. Alle drei Artefakte sind freigegeben."
_NEXT_STEP = {
    "01": "Als Nächstes folgt die Projektbeschreibung.",
    "02": "Als Nächstes folgt die Stakeholder-Analyse.",
    "03": "Als Nächstes folgen die offenen Punkte.",
}


def greeting_for(slots: list[tuple[str, str]]) -> str:
    """Greeting for a new chat from (slot, status) pairs."""
    if all(status == "not_started" for _, status in slots):
        return GREETING_NEW
    for slot, status in sorted(slots):
        if status != "approved":
            return f"Willkommen zurück. {_NEXT_STEP[slot]}"
    return GREETING_ALL_APPROVED
